package com.realstant.nativegame; import java.util.*; public final class CheckpointSystem { private final List<Checkpoint> points=new ArrayList<>(); private int next; public void build(){points.clear(); for(int i=0;i<20;i++)points.add(new Checkpoint(i,(float)Math.sin(i*.8)*18f,i*45f));next=0;} public void update(float x,float z){if(next<points.size()){Checkpoint c=points.get(next);float dx=x-c.x,dz=z-c.z;if(dx*dx+dz*dz<100){c.passed=true;next++;}}} public int progress(){return next;} }
